use std::hint::black_box;
use std::time::Instant;

const RAW_DATA: &str = "";
const DATA: &[u8] = RAW_DATA.as_bytes();

pub fn find_first_fourteen(input: &[u8]) -> Option<usize> {
  let mut idx = 0;
  while let Some(slice) = input.get(idx..idx + 14) {
    let mut state = 0u32;

    if let Some(pos) = slice.iter().rposition(|byte| {
      let bit_idx = byte % 32;
      let ret = state & (1 << bit_idx) != 0;
      state |= 1 << bit_idx;
      ret
    }) {
      idx += pos + 1;
    } else {
      return Some(idx);
    }
  }
  return None;
}

fn main() {
  let mut start = None;

  let before = Instant::now();
  for _ in 0..100 {
    start = black_box(find_first_fourteen(black_box(DATA)));
  }
  let average = before.elapsed().as_nanos() as f64 / 100.0;

  println!("find_first_fourteen found {:?} and took {} nanoseconds", start, average);
}
